let state;try{state=JSON.parse(localStorage.getItem(STORAGE_KEY));if(state?.version!==1||(!Array.isArray(state.results)&&!state.deviceResults))throw 0;normalizeDeviceState(state);normalizeLocationState(state);}catch{state=sampleState();if(isLocal){state.mode='actual';state.restaurant={name:'내 매장을 등록해 주세요',placeId:'',url:'',address:'매장명과 네이버 지도 URL로 시작하세요'};state.results=[];state.settings.endpoint=location.origin;}normalizeDeviceState(state);normalizeLocationState(state);}
