const mapSearchUrl = (keyword,device=state.activeDevice) => {
  if(device==='mobile')return 'https://m.map.naver.com/search?query='+encodeURIComponent(keyword);
  let url='https://map.naver.com/p/search/'+encodeURIComponent(keyword);const point=state.settings.searchLocation;
  if(point&&Math.abs(point.latitude)<85.0511){const x=6378137*point.longitude*Math.PI/180,y=6378137*Math.log(Math.tan(Math.PI/4+point.latitude*Math.PI/360));url+='?c='+[x.toFixed(4),y.toFixed(4),15,0,0,0,'dh'].join(',');}
  return url;
};
let filter='all',search='',page=1,sortKey='',sortDirection=1,period=7,selected=new Set(),scanning=false,controller,toastTimer;
