function persist(){try{stashCurrentLocation(state);const saved={...state,locationProfiles:{...state.locationProfiles}};delete saved.locationProfiles[state.locationKey];delete saved.results;localStorage.setItem(STORAGE_KEY,JSON.stringify(saved));}catch{toast('브라우저 저장 공간이 부족해 이번 변경은 현재 탭에만 유지됩니다.');}}
