function renderDonut(s){
  const colors=['#f4754d','#fab393','#a5b2c6','#e2e7ed','#c5b9df'],labels=['TOP 3','4–10위','11위 이하','일반 미노출','대기 / 오류'];
  const total=s.total||1,C=2*Math.PI*81;let offset=0;
  $('#donut-chart').innerHTML=`<circle cx="110" cy="110" r="81" fill="none" stroke="#f1f3f6" stroke-width="24"/>`+s.distribution.map((n,i)=>{const len=n/total*C,gap=n?Math.min(4,len/4):0;const out=`<circle cx="110" cy="110" r="81" fill="none" stroke="${colors[i]}" stroke-width="24" stroke-dasharray="${Math.max(0,len-gap)} ${C-Math.max(0,len-gap)}" stroke-dashoffset="${-offset}" transform="rotate(-90 110 110)"><title>${labels[i]}: ${n}개</title></circle>`;offset+=len;return out;}).join('');
  $('#distribution-legend').innerHTML=s.distribution.map((n,i)=>`<div><span><i class="legend-dot" style="background:${colors[i]}"></i>${labels[i]}</span><strong>${n}<small>개</small><em>${Math.round(n/total*100)}%</em></strong></div>`).join('');
}
function renderTrend(){
  const series=historySeries(state.results,period),chart=$('#trend-chart');
  if(!series.length){chart.innerHTML='<div class="chart-empty">첫 측정이 완료되면 순위 추이를 확인할 수 있어요.</div>';$('#trend-caption').textContent='측정 버튼을 눌러 첫 관측 기록을 만들어 보세요.';return;}
  const W=760,H=226,p={l:40,r:24,t:16,b:30},all=series.flatMap(s=>[s.organic,s.ads]).filter(Number.isFinite),max=Math.max(5,Math.ceil(Math.max(...all,5)/5)*5);
  const x=i=>series.length===1?(W+p.l-p.r)/2:p.l+i*(W-p.l-p.r)/(series.length-1),y=v=>p.t+(v-1)/(max-1)*(H-p.t-p.b);
  const ticks=[1,...Array.from({length:4},(_,i)=>Math.round(1+(max-1)*(i+1)/4))];
  const grid=ticks.map(v=>`<line class="chart-grid-line" x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis-label" x="${p.l-12}" y="${y(v)+4}" text-anchor="end">${v}위</text>`).join('');
  const path=key=>{let out='',gap=true;series.forEach((s,i)=>{if(s[key]===null){gap=true;return;}out+=`${gap?'M':'L'}${x(i)},${y(s[key])} `;gap=false;});return out;};
  const points=key=>series.map((s,i)=>s[key]===null?'':`<circle cx="${x(i)}" cy="${y(s[key])}" r="4" fill="${key==='organic'?'#f4754d':'#a497cf'}" stroke="white" stroke-width="2"><title>${s.date} ${key==='organic'?'일반':'광고'} 평균 ${s[key].toFixed(1)}위</title></circle>`).join('');
  const area=series.every(s=>s.organic!==null)?`${path('organic')}L${x(series.length-1)},${H-p.b} L${x(0)},${H-p.b} Z`:'';
  chart.innerHTML=`<svg class="trend-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${series.length}일간 평균 일반 순위와 광고 순위 추이. 숫자가 작을수록 상위 순위."><defs><linearGradient id="area-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#f4754d" stop-opacity=".15"/><stop offset="100%" stop-color="#f4754d" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#area-gradient)"/><path class="chart-line-organic" d="${path('organic')}"/><path class="chart-line-ad" d="${path('ads')}"/>${points('organic')}${points('ads')}${series.filter((_,i)=>series.length<10||i%Math.ceil(series.length/7)===0||i===series.length-1).map(s=>`<text class="chart-axis-label" x="${x(series.indexOf(s))}" y="${H-6}" text-anchor="middle">${s.date.slice(5).replace('-','.')}</text>`).join('')}</svg>`;
  $('#trend-caption').textContent=state.mode==='demo'?`샘플 데이터 · ${series.length}일 기록 · 숫자가 작을수록 상위 순위입니다.`:`${series.length}일의 관측 기록 · ${series.length<2?'측정이 쌓이면 추세선이 연결됩니다.':'일별 최신 측정의 평균입니다.'}`;
}
function filteredResults(){let data=state.results.filter(r=>(!search||r.keyword.toLowerCase().includes(search))&&(filter==='all'||filter==='top10'&&r.status==='success'&&r.organicRank!==null&&r.organicRank<=10||filter==='ads'&&r.status==='success'&&r.adRank!==null||filter==='unranked'&&(r.status!=='success'||r.organicRank===null)));
  if(sortKey)data.sort((a,b)=>sortKey==='keyword'?sortDirection*a.keyword.localeCompare(b.keyword,'ko'):sortDirection*((a[sortKey]??Infinity)-(b[sortKey]??Infinity)));return data;}
function renderTable(showAll=false){const data=filteredResults(),pages=Math.max(1,Math.ceil(data.length/PAGE_SIZE));page=Math.min(page,pages);const rows=showAll?data:data.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
  $('#keyword-tbody').innerHTML=rows.map(r=>{const ok=r.status==='success',rank=r.organicRank,change=ok&&Number.isFinite(rank)&&Number.isFinite(r.previousRank)?r.previousRank-rank:null;
    const rankClass=rank<=3?'rank-top':rank<=10?'rank-mid':'rank-low';
    const label=r.status==='error'?'측정 오류':r.status==='pending'?'측정 대기':rank===null?'일반 미노출':rank<=10?'상위 노출':'일반 노출';
    const statusClass=r.status==='error'?'status-error':r.status==='pending'||rank===null?'status-none':rank<=10?'status-top':'status-visible';
    return `<tr><td class="check-cell"><input type="checkbox" data-select="${esc(r.keyword)}" ${selected.has(r.keyword)?'checked':''} aria-label="${esc(r.keyword)} 선택"></td><td><button class="keyword-name" data-detail="${esc(r.keyword)}">${esc(r.keyword)}</button>${r.source==='demo'?'<span class="row-demo">DEMO</span>':''}</td><td>${ok?rank===null?`<span class="rank-unranked">미노출</span>`:`<span class="rank-value ${rankClass}">${rank}<small>위</small></span>`:'<span class="muted">—</span>'}</td><td><span class="rank-change ${change>0?'positive':change<0?'negative':'neutral'}">${change===null?'—':change===0?'−':`${change>0?'↑':'↓'} ${Math.abs(change)}`}</span></td><td>${ok?r.adRank!==null?`<span class="ad-badge"><small>AD</small> ${r.adRank}위</span>`:'<span class="ad-none">광고 미노출</span>':'<span class="muted">—</span>'}</td><td><span class="status-badge ${statusClass}"><i></i>${label}</span></td><td class="align-right"><a class="result-link" href="${esc(mapSearchUrl(r.keyword,r.device))}" target="_blank" rel="noopener noreferrer" aria-label="${esc(r.keyword)} 네이버 지도 검색 결과 열기">${icon('arrow-up-right')}</a></td></tr>`;}).join('');
  $('#empty-results').hidden=data.length!==0;
  $('#pagination-label').textContent=data.length?`전체 ${data.length}개 중 ${(page-1)*PAGE_SIZE+1}–${Math.min(page*PAGE_SIZE,data.length)}개`:'0개 키워드';
  $('#pagination').innerHTML=`<button data-page="${page-1}" ${page===1?'disabled':''} aria-label="이전 페이지">‹</button>`+Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-page)<=1).map((n,i,a)=>(i&&n-a[i-1]>1?'<span>…</span>':'')+`<button data-page="${n}" class="${n===page?'selected':''}" aria-label="${n}페이지" ${n===page?'aria-current="page"':''}>${n}</button>`).join('')+`<button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="다음 페이지">›</button>`;
  $('#select-all').checked=rows.length>0&&rows.every(r=>selected.has(r.keyword));$('#selected-actions').hidden=!selected.size;
}
function showModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;hydrateIcons($('#modal'));if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function errorForm(text){let el=$('#form-error');if(el){el.textContent=text;el.hidden=false;}else toast(text);}
function keywordsModal(){showModal('성장의 시작, 키워드 추가',`<p class="modal-description">줄바꿈, 쉼표 또는 탭으로 여러 키워드를 한 번에 추가하세요.<br>중복은 자동으로 정리하며 최대 1,000개까지 관리할 수 있어요.</p><form id="keywords-form"><div class="form-field"><label for="bulk-keywords">분석할 키워드</label><textarea id="bulk-keywords" rows="8" placeholder="성수 맛집&#10;성수 파스타&#10;서울숲 데이트" required></textarea><div class="keyword-counter"><span>한 줄에 하나씩, 붙여넣기도 가능해요.</span><strong id="bulk-count">0개</strong></div></div><div class="callout">키워드를 추가한 뒤 ‘순위 측정 시작’을 누르면 네이버 지도를 조회합니다.</div><p class="form-error" id="form-error" hidden></p><div class="modal-actions"><button type="button" class="button button-white" data-close>취소</button><button class="button button-primary" type="submit">키워드 추가 ${icon('plus')}</button></div></form>`);$('#bulk-keywords').addEventListener('input',e=>$('#bulk-count').textContent=parseKeywords(e.target.value).length+'개');}
function storeModal(){showModal('어떤 매장의 성장을 볼까요?',`<p class="modal-description">네이버 지도에서 매장을 찾은 뒤 주소를 붙여넣어 주세요.<br>플레이스 ID로 같은 이름의 다른 매장과 정확히 구분합니다.</p><form id="store-form"><div class="form-field"><label for="restaurant-name">매장명</label><input id="restaurant-name" value="${esc(state.mode==='demo'||!state.restaurant.placeId?'':state.restaurant.name)}" placeholder="예: 성수온실" maxlength="80" required></div><div class="form-field"><label for="restaurant-url">네이버 지도 URL 또는 플레이스 ID</label><input id="restaurant-url" value="${esc(state.restaurant.url||state.restaurant.placeId)}" placeholder="https://map.naver.com/p/entry/place/123456789" required><p class="helper-text">map.naver.com 또는 m.place.naver.com의 매장 상세 URL을 입력해 주세요. naver.me 단축 주소는 펼친 뒤 입력하세요.</p></div><div class="form-field"><label for="restaurant-address">지역 / 매장 설명</label><input id="restaurant-address" value="${esc(state.mode==='demo'||!state.restaurant.placeId?'':state.restaurant.address)}" placeholder="서울 성동구 · 이탈리안 레스토랑" maxlength="100"></div><div class="callout">매장을 변경하면 기존 측정값과 추이를 초기화합니다. 등록한 키워드는 유지하며 다시 측정할 수 있어요.</div><p class="form-error" id="form-error" hidden></p><div class="modal-actions"><button type="button" class="button button-white" data-close>취소</button><button class="button button-primary">매장 저장</button></div></form>`);}
async function loadRegionCatalog(){
  if(regionCatalog)return;
  try{const response=await fetch('regions.json',{cache:'no-cache'});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.provinces)||!data.provinces.length)throw Error();regionCatalog=data;regionLoadError='';}
  catch{regionLoadError='지역 목록을 불러오지 못했어요. 화면을 새로고침한 뒤 다시 열어 주세요.';}
}
function provinceByCode(code){return regionCatalog?.provinces.find(province=>String(province.code)===String(code));}
function regionCityOptions(provinceCode,cityCode=''){
  const province=provinceByCode(provinceCode);
  if(!province)return '<option value="">시·군·구를 선택하세요</option>';
  const options=province.cities.map(city=>`<option value="${esc(city.code)}" ${String(city.code)===String(cityCode)?'selected':''}>${esc(city.name)}</option>`).join('');
  return '<option value="">'+esc(province.name)+' 대표 지역</option>'+options;
}
function locationFields(){
  const current=state.settings.searchLocation;locationDraft=current?structuredClone(current):null;regionSearchPending=false;
  const match=current&&regionCatalog?matchRegionSelection(regionCatalog,current):null;
  const provinceOptions=(regionCatalog?.provinces||[]).map(province=>`<option value="${esc(province.code)}" ${match?.provinceCode===province.code?'selected':''}>${esc(province.displayName||province.name)}</option>`).join('');
  const saved=Object.entries(state.locationProfiles||{}).filter(([key,profile])=>key!=='default'&&key!==state.locationKey&&profile.searchLocation);
  const savedButtons=saved.map(([key,profile])=>`<button type="button" data-saved-region="${esc(key)}">${esc(friendlyRegionName(profile.searchLocation))}</button>`).join('');
  const savedBlock=savedButtons?'<details class="region-history"><summary>이전에 선택한 지역</summary><div class="region-history-list">'+savedButtons+'</div></details>':'';
  const keepCurrent=current?'<button type="button" class="text-button" id="region-keep-current">현재 지역 유지</button>':'';
  const unavailable=regionLoadError?'<p class="form-error">'+esc(regionLoadError)+'</p>':'';
  return `<fieldset class="location-fieldset region-fieldset"><legend>검색 지역</legend><div class="form-field"><label for="region-search">지역 이름으로 찾기</label><div class="region-search-input">${icon('search')}<input id="region-search" type="search" placeholder="예: 경기도 수원시, 부산 해운대구" autocomplete="off" aria-controls="region-search-results" aria-expanded="false"></div><div id="region-search-results" class="region-search-results" aria-label="지역 검색 결과" hidden></div></div>${unavailable}<div class="form-grid region-select-grid"><div class="form-field"><label for="region-province">시·도</label><select id="region-province"><option value="">시·도를 선택하세요</option>${provinceOptions}</select></div><div class="form-field"><label for="region-city">시·군·구</label><select id="region-city" ${!match?'disabled':''}>${regionCityOptions(match?.provinceCode,match?.cityCode||'')}</select></div></div><div class="region-picked" role="status">${icon('pin')}<div><small>선택한 검색 지역</small><strong id="region-picked-name">${esc(friendlyRegionName(current))}</strong><p id="region-picked-help">${current?'저장된 검색 기준 위치를 유지합니다.':'지역을 고르면 검색 기준 위치를 자동으로 설정합니다.'}</p></div></div><div class="region-mode-actions">${keepCurrent}<button type="button" class="text-button" id="region-use-default">네이버 기본 위치 사용</button></div>${savedBlock}<p class="helper-text region-source">지역별 대표 위치를 기준으로 검색합니다. 행정구역 전체의 결과를 합산하는 방식은 아닙니다.</p></fieldset>`;
}
function bindLocationFields(){
  const provinceSelect=$('#region-province'),citySelect=$('#region-city'),searchInput=$('#region-search'),resultsBox=$('#region-search-results');if(!provinceSelect)return;
  const original=state.settings.searchLocation?structuredClone(state.settings.searchLocation):null;let searchResults=[];
  function hideSearch(){resultsBox.hidden=true;searchInput.setAttribute('aria-expanded','false');}
  function showPicked(point,help){locationDraft=point?normalizeSearchLocation(point):null;$('#region-picked-name').textContent=friendlyRegionName(locationDraft);$('#region-picked-help').textContent=help||'선택한 지역의 검색 기준 위치를 자동으로 설정합니다.';}
  function displaySelection(selection){provinceSelect.value=selection?.provinceCode||'';citySelect.innerHTML=regionCityOptions(selection?.provinceCode,selection?.cityCode||'');citySelect.disabled=!selection;citySelect.value=selection?.cityCode||'';}
  function clearSearch(){searchInput.value='';regionSearchPending=false;hideSearch();}
  function choose(selection){displaySelection(selection);showPicked(selection,'지역 이름으로 검색 기준 위치를 찾았어요. 적용을 누르세요.');searchInput.value=selection.label;regionSearchPending=false;hideSearch();}
  provinceSelect.addEventListener('change',()=>{clearSearch();const province=provinceByCode(provinceSelect.value);citySelect.innerHTML=regionCityOptions(provinceSelect.value);citySelect.disabled=!province;if(province)showPicked(getRegionSelection(regionCatalog,provinceSelect.value),'시·군·구를 고르면 더 자세한 지역으로 설정할 수 있어요.');else showPicked(null);});
  citySelect.addEventListener('change',()=>{clearSearch();if(provinceSelect.value)showPicked(getRegionSelection(regionCatalog,provinceSelect.value,citySelect.value));});
  searchInput.addEventListener('input',()=>{const query=searchInput.value.trim();regionSearchPending=Boolean(query);searchResults=query&&regionCatalog?searchRegions(regionCatalog,query,12):[];if(!query){hideSearch();return;}const rows=searchResults.map((result,index)=>`<button type="button" class="region-search-result" data-region-result="${index}"><strong>${esc(result.label)}</strong><span>선택</span></button>`).join('');resultsBox.innerHTML=rows||'<p class="region-no-results">일치하는 지역이 없어요. 시·도와 시·군·구 이름으로 찾아보세요.</p>';resultsBox.hidden=false;searchInput.setAttribute('aria-expanded','true');});
  searchInput.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();if(searchResults.length)choose(searchResults[0]);else if(searchInput.value.trim())errorForm('검색 결과에서 지역을 선택해 주세요.');}if(event.key==='Escape'){event.preventDefault();hideSearch();}if(event.key==='ArrowDown'&&searchResults.length){event.preventDefault();resultsBox.querySelector('button')?.focus();}});
  resultsBox.addEventListener('click',event=>{const button=event.target.closest('[data-region-result]');if(button)choose(searchResults[Number(button.dataset.regionResult)]);});
  $('#region-use-default').addEventListener('click',()=>{clearSearch();displaySelection(null);showPicked(null,'네이버 기본 검색 위치를 사용합니다.');});
  $('#region-keep-current')?.addEventListener('click',()=>{clearSearch();displaySelection(original&&regionCatalog?matchRegionSelection(regionCatalog,original):null);showPicked(original,'이전에 저장한 검색 기준 위치를 그대로 유지합니다.');});
  document.querySelectorAll('[data-saved-region]').forEach(button=>button.addEventListener('click',()=>{const point=state.locationProfiles[button.dataset.savedRegion]?.searchLocation;if(point){clearSearch();displaySelection(regionCatalog?matchRegionSelection(regionCatalog,point):null);showPicked(point,'이전에 측정한 위치로 돌아가면 기록을 다시 볼 수 있어요.');}}));
}
function readLocationFields(){if(regionSearchPending)throw Error('지역 검색 결과에서 사용할 지역을 선택해 주세요.');return locationDraft?normalizeSearchLocation(locationDraft):null;}
const locationExplanation=`<div class="callout">선택한 지역이 네이버 검색에 적용됐는지 확인한 뒤 순위를 기록합니다. 키워드에 다른 지역명이 들어 있으면 그 지역 결과가 우선될 수 있습니다.</div><p class="helper-text">앱이 지역의 기준 위치를 자동으로 처리합니다. PC의 검색 중심점과 모바일 웹의 기준 위치에 적용되며, 접속 IP·광고 개인화는 별도입니다.</p>`;
async function locationModal(){await loadRegionCatalog();showModal('검색할 지역을 선택하세요',`<p class="modal-description">지역 이름을 검색하거나 시·도와 시·군·구를 선택하세요.<br>기존 측정값은 지역별로 보관하고 다시 선택하면 복원합니다.</p><form id="location-form">${locationFields()}<p class="form-error" id="form-error" hidden></p><div class="modal-actions"><button type="button" class="button button-white" data-close>취소</button><button class="button button-primary">검색 지역 적용</button></div></form>`);bindLocationFields();}
async function settingsModal(){await loadRegionCatalog();showModal('측정 환경 설정',`<p class="modal-description">${isLocal?'파이썬 서버와 자동으로 연결됐어요. 기기와 검색 기준 지역을 선택하세요.':'시작하기.cmd를 더블클릭하면 실제 측정을 시작할 수 있어요.'}</p><form id="settings-form"><div class="form-field"><label for="collector-endpoint">파이썬 수집기 연결</label><div class="inline-field"><input id="collector-endpoint" type="url" value="${esc(collectorEndpoint())}" ${isLocal?'readonly':''}><button type="button" class="button button-white" id="test-connection">연결 확인</button></div><p class="helper-text" id="connection-status">${esc(connectionLabel)}</p></div>${locationFields()}<div class="form-grid"><div class="form-field"><label for="setting-depth">조회 요청 범위</label><select id="setting-depth">${[20,50,100].map(n=>`<option value="${n}" ${state.settings.maxDepth===n?'selected':''}>최대 ${n}위 요청</option>`).join('')}</select></div><div class="form-field"><label for="setting-device">측정 기기</label><select id="setting-device"><option value="desktop" ${state.activeDevice==='desktop'?'selected':''}>PC 웹</option><option value="mobile" ${state.activeDevice==='mobile'?'selected':''}>모바일 웹 에뮬레이션</option></select></div></div><div class="form-field"><label for="setting-region">환경 메모 (선택)</label><input id="setting-region" value="${esc(state.settings.region||'')}" maxlength="100" placeholder="예: 점심 시간 측정"><p class="helper-text">위 검색 지역과 별개로 남기는 기록용 메모입니다.</p></div>${locationExplanation}<p class="form-error" id="form-error" hidden></p><div class="modal-actions"><button type="button" class="button button-white" data-close>취소</button><button class="button button-primary">설정 저장</button></div></form>`);bindLocationFields();testConnection();}
function methodologyModal(){showModal('숫자를 읽는 정확한 기준',`<p class="modal-description">순위는 특정 시점과 환경에서 관측한 검색 결과입니다.</p><div class="method-grid"><div class="method-box"><strong>일반 순위</strong><p>광고 항목을 제외한 일반 결과에서 해당 매장이 등장한 순번입니다. 광고를 중단한 이후의 순위를 예측하는 값이 아닙니다.</p></div><div class="method-box"><strong>광고 순위</strong><p>현재 검색 결과에서 관측한 광고 항목 사이의 순번입니다. ‘광고 미노출’은 조회 범위에서 발견되지 않았다는 뜻입니다.</p></div><div class="method-box"><strong>일반 미노출</strong><p>정해진 조회 범위에서 일반 결과를 찾지 못했습니다. 차단·실패·미완료는 미노출로 계산하지 않고 오류/대기로 표시합니다.</p></div><div class="method-box"><strong>차트와 평균</strong><p>평균은 노출된 키워드만, TOP 10 비율은 측정 완료 키워드를 기준으로 계산합니다. 추이는 일별 최신 기록의 평균입니다.</p></div></div><div class="callout">개인화·검색 위치·디바이스·시간에 따라 결과가 달라집니다. 검색 지역을 고르면 앱이 해당 지역의 검색 기준 위치를 자동으로 설정합니다. PC는 지도 검색 중심점, 모바일은 웹 기준 위치이며 실제 기기 GPS·접속 IP·광고 개인화와 다를 수 있습니다.</div><p class="helper-text">공식 참고: <a target="_blank" rel="noopener" href="https://developers.naver.com/docs/serviceapi/search/local/local.md">네이버 지역검색 API</a> · <a target="_blank" rel="noopener" href="https://help.naver.com/service/30026/contents/25605?lang=ko">광고 노출 조건</a></p><div class="modal-actions"><button class="button button-primary" data-close>확인했어요</button></div>`);}
function guideModal(){showModal('숫자에서 다음 액션까지',`<p class="modal-description">플레이스 랭크를 시작하는 네 가지 단계.</p><div class="method-grid"><div class="method-box"><strong>01 · 내 매장 등록</strong><p>시작하기.cmd를 더블클릭한 뒤, ‘매장 등록하기’에서 매장명과 네이버 지도 URL을 입력하세요.</p></div><div class="method-box"><strong>02 · 키워드 대량 추가</strong><p>지역, 메뉴, 방문 목적별 키워드를 붙여넣으세요. 중복은 자동으로 정리됩니다.</p></div><div class="method-box"><strong>03 · 실제 데이터 측정</strong><p>‘순위 측정 시작’을 누르세요. 파이썬 수집기가 광고와 일반 노출을 따로 측정합니다.</p></div><div class="method-box"><strong>04 · 성장 리포트 완성</strong><p>추이와 분포를 확인한 뒤 CSV 또는 인쇄용 리포트로 저장하세요.</p></div></div><div class="modal-actions"><button class="button button-white" data-action="methodology">순위 산정 기준</button><button class="button button-primary" data-action="store">내 매장 등록</button></div>`);}
function importModal(){showModal('측정 데이터를 가져오세요',`<p class="modal-description">CSV 또는 JSON 파일을 분석할 수 있어요. 최대 1,000개 키워드·두 기기 합계 2,000행, 5MB까지 지원합니다.</p><button class="upload-zone" id="choose-import">${icon('upload')}<strong>측정 파일 선택</strong><span>.csv 또는 .json 파일</span></button><p class="helper-text">필수 열: keyword, organicRank, adRank, observedAt<br>추가 열: placeId, restaurant, device, region, maxDepth, source, status<br>지역 필드: searchLocationLabel, searchLatitude, searchLongitude, locationApplied<br>빈 순위는 ‘조회 범위 내 미노출’로 처리합니다. 측정 시각은 시간대를 포함한 ISO 형식을 권장합니다.</p><div class="callout">가져오는 파일은 현재 매장의 한 검색 지역 데이터여야 합니다. 데이터가 겹치면 키워드별 최신 측정이 반영되며 이전 기록은 추이에 남습니다.</div><div class="modal-actions"><button class="button button-white" id="download-template">CSV 양식 다운로드</button><button class="button button-primary" id="choose-import-bottom">파일 선택</button></div>`);}
function exportModal(){showModal('성장을 기록하는 리포트',`<p class="modal-description">현재 워크스페이스의 측정값과 분석 결과를 저장하세요.</p><div class="method-grid"><button class="method-box export-option" id="export-csv">${icon('download')}<strong>데이터 CSV</strong><p>현재 검색 지역의 PC·모바일 순위, 좌표와 측정 환경. 엑셀에서 바로 열 수 있어요.</p></button><button class="method-box export-option" id="print-report">${icon('report')}<strong>인쇄 / PDF 리포트</strong><p>현재 선택한 기기의 지표·차트·전체 키워드를 인쇄하거나 PDF로 저장하세요.</p></button></div><div class="callout">${state.mode==='demo'?'샘플 데이터 리포트에는 demo 출처가 명시됩니다.':'리포트에 측정 시각, 조회 환경과 출처를 함께 기록합니다.'}</div>`);}
function reportsModal(){showModal('리포트 보관함',state.reports?.length?`<p class="modal-description">이 브라우저에서 내보낸 리포트의 기록입니다. 원본 파일은 다운로드 폴더에서 확인하세요.</p>${state.reports.slice().reverse().map(r=>`<div class="report-item">${icon('report')}<div><strong>${esc(r.name)}</strong><small>${fmtDate(r.date)} · ${r.count}개 키워드 · ${esc(r.mode)}</small></div><span class="tag tag-neutral">${esc(r.type)}</span></div>`).join('')}<div class="modal-actions"><button class="button button-primary" data-action="export">새 리포트 만들기</button></div>`:'<div class="empty-state">'+icon('report')+'<h3>첫 성장 리포트를 만들어 보세요</h3><p>CSV 내보내기와 PDF 인쇄 기록을 이곳에서 확인할 수 있어요.</p><button class="button button-primary" data-action="export">리포트 내보내기</button></div>');}
function detailModal(keyword){const r=state.results.find(x=>x.keyword===keyword);if(!r)return;showModal(keyword,`<p class="modal-description">${esc(state.restaurant.name)} · ${r.source==='demo'?'샘플 관측 기록':r.source==='import'?'파일에서 가져온 기록':'네이버 지도 관측 기록'}</p><div class="method-grid"><div class="method-box"><strong>일반 순위</strong><p>${r.status==='success'?r.organicRank===null?`${r.maxDepth}위 범위 내 미노출`:r.organicRank+'위':'측정값 없음'}</p></div><div class="method-box"><strong>광고 순위</strong><p>${r.status==='success'?r.adRank===null?'조회 범위 내 광고 미노출':r.adRank+'위':'측정값 없음'}</p></div><div class="method-box"><strong>측정 시각 · 기기</strong><p>${fmtDate(r.observedAt)}<br>${esc(deviceLabel(r.device||state.activeDevice))}</p></div><div class="method-box"><strong>환경 · 조회 범위</strong><p>${esc(r.region||state.settings.region)}<br>일반 결과 최대 ${r.maxDepth??state.settings.maxDepth}위<br>${esc((r.searchLocation||r.requestedSearchLocation)?.label||'네이버 기본 위치')}<br>${r.locationApplied===true?'선택 지역 적용 확인':r.requestedSearchLocation?'선택 지역 적용 미확인':'지역 좌표 미지정'}</p></div></div>${r.locationVerification?`<div class="callout">${esc(typeof r.locationVerification==='string'?r.locationVerification:(r.locationVerification.description||'네이버 검색의 선택 좌표 반영을 확인했습니다.'))}</div>`:''}${r.error?`<div class="callout form-error">${esc(r.error)}</div>`:''}<div class="modal-actions"><a class="button button-primary" target="_blank" rel="noopener" href="${esc(mapSearchUrl(keyword,r.device))}">지도에서 확인 ${icon('arrow-up-right')}</a></div>`);}
const actions={location:locationModal,keywords:keywordsModal,store:storeModal,settings:settingsModal,methodology:methodologyModal,guide:guideModal,import:importModal,export:exportModal,reports:reportsModal};
document.addEventListener('click',e=>{
  const deviceButton=e.target.closest('[data-device]');if(deviceButton){if(scanning){toast('조회가 끝난 뒤 기기를 변경해 주세요.');return;}activateDevice(state,deviceButton.dataset.device);selected.clear();page=1;persist();render();return;}
  const action=e.target.closest('[data-action]');if(action){actions[action.dataset.action]?.();return;}
  if(e.target.closest('[data-close]'))closeModal();
  const detail=e.target.closest('[data-detail]');if(detail)detailModal(detail.dataset.detail);
  const periodButton=e.target.closest('[data-period]');if(periodButton){period=Number(periodButton.dataset.period);document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b===periodButton));renderTrend();}
  const filterButton=e.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;page=1;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===filterButton));renderTable();}
  const pageButton=e.target.closest('[data-page]');if(pageButton&&!pageButton.disabled){page=Number(pageButton.dataset.page);renderTable();}
  const sort=e.target.closest('[data-sort]');if(sort){sortDirection=sortKey===sort.dataset.sort?-sortDirection:1;sortKey=sort.dataset.sort;renderTable();}
  if(e.target.closest('#choose-import,#choose-import-bottom'))$('#import-file').click();
  if(e.target.closest('#test-connection'))testConnection();
  if(e.target.closest('#download-template'))download('place-rank-template.csv',csvEncode([['keyword','organicRank','adRank','observedAt','placeId','restaurant','device','region','maxDepth','source','status'],['예시 키워드','','','2026-11-06T14:30:00+09:00','','내 매장','desktop','서울 성동구',100,'manual','success']]),'text/csv;charset=utf-8');
  if(e.target.closest('#export-csv'))exportCSV();
  if(e.target.closest('#print-report'))printReport();
});
document.addEventListener('submit',e=>{
  if(e.target.id==='keywords-form'){e.preventDefault();const keys=parseKeywords($('#bulk-keywords').value);if(!keys.length)return errorForm('키워드를 한 개 이상 입력해 주세요.');if(keys.some(k=>k.length>100))return errorForm('키워드는 하나당 100자 이내로 입력해 주세요.');const added=keys.filter(k=>!state.results.some(r=>r.keyword===k));if(state.results.length+added.length>1000)return errorForm('총 1,000개까지 관리할 수 있습니다.');state.results.push(...added.map(keyword=>({keyword,device:state.activeDevice,organicRank:null,adRank:null,status:'pending',maxDepth:state.settings.maxDepth,source:state.mode==='demo'?'demo':'naver-map'})));persist();render();closeModal();toast(`${added.length}개 추가 · 중복은 자동 정리했어요. 이제 순위 측정을 시작하세요.`);window.scrollTo({top:0,behavior:'smooth'});}
  if(e.target.id==='store-form'){e.preventDefault();if(scanning)return errorForm('조회가 끝난 뒤 매장을 변경해 주세요.');const name=$('#restaurant-name').value.trim(),url=$('#restaurant-url').value.trim(),placeId=parsePlaceId(url);if(!name||!placeId)return errorForm('매장명과 유효한 네이버 매장 상세 URL 또는 숫자 ID를 입력해 주세요.');const firstRegistration=state.mode==='demo'||!state.restaurant.placeId;const keywords=state.mode==='demo'?[]:[...new Set(allDeviceRows(state).map(row=>row.keyword))];state.restaurant={name,url,placeId,address:$('#restaurant-address').value.trim()};state.mode='actual';state.deviceResults={desktop:[],mobile:[]};state.locationProfiles={};state.keywordRegistry=[...keywords];state.results=keywords.map(keyword=>({keyword,device:state.activeDevice,status:'pending',organicRank:null,adRank:null,maxDepth:state.settings.maxDepth,source:'naver-map'}));selected.clear();persist();render();closeModal();toast('매장을 등록했어요. 분석할 키워드를 추가해 주세요.');if(firstRegistration||!state.results.length)keywordsModal();}
  if(e.target.id==='location-form'){e.preventDefault();if(scanning)return errorForm('조회가 끝난 뒤 지역을 변경해 주세요.');try{const location=readLocationFields();changeSearchLocation(state,location);selected.clear();page=1;persist();render();closeModal();toast(`검색 기준 지역: ${locationName()} · 측정 버튼을 누르면 적용 여부를 확인합니다.`);}catch(error){errorForm(error.message);}}
  if(e.target.id==='settings-form'){e.preventDefault();if(scanning)return errorForm('조회가 끝난 뒤 설정을 변경해 주세요.');try{const endpoint=isLocal?location.origin:$('#collector-endpoint').value.trim().replace(/\/$/,'');if(!validEndpoint(endpoint))throw Error('localhost 또는 127.0.0.1 주소를 입력해 주세요.');const searchLocation=readLocationFields(),device=$('#setting-device').value,region=$('#setting-region').value.trim(),maxDepth=Number($('#setting-depth').value);changeSearchLocation(state,searchLocation);state.settings={...state.settings,endpoint,region,maxDepth};activateDevice(state,device);selected.clear();page=1;persist();render();closeModal();toast('검색 지역과 측정 설정을 저장했어요.');}catch(error){errorForm(error.message);}}

});
function validEndpoint(endpoint){try{const u=new URL(endpoint);return ['localhost','127.0.0.1','[::1]'].includes(u.hostname)&&u.protocol==='http:'&&!u.username&&!u.password&&u.pathname==='/';}catch{return false;}}
async function checkHealth(endpoint){const response=await fetch(endpoint+'/api/health',{signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error('서버 응답 오류');const data=await response.json();if(data.service!=='place-rank-python'||data.runtime!=='python')throw Error('파이썬 수집기를 실행해 주세요.');return data;}
async function refreshConnection(){try{const data=await checkHealth(collectorEndpoint());connectionLabel=data.collectorReady?'파이썬 수집기 준비 완료':'조회 브라우저 설치 필요';}catch{connectionLabel='시작하기.cmd 실행 필요';}const status=$('.system-status');if(status){status.innerHTML='<i></i>'+esc(connectionLabel);}render();}
async function testConnection(){const endpoint=isLocal?location.origin:$('#collector-endpoint').value.trim().replace(/\/$/,'');if(!validEndpoint(endpoint))return errorForm('localhost 또는 127.0.0.1의 HTTP 주소를 입력해 주세요.');const el=$('#connection-status');if(el)el.textContent='연결 확인 중…';try{const data=await checkHealth(endpoint);connectionLabel=data.collectorReady?'파이썬 수집기 준비 완료':'조회 브라우저 설치 필요';if(el?.isConnected)el.textContent=data.collectorReady?'연결 완료 · 바로 순위를 측정할 수 있어요.':data.message;}catch{connectionLabel='시작하기.cmd 실행 필요';if(el?.isConnected)el.textContent='연결할 수 없어요. 시작하기.cmd를 실행하고 열린 창을 유지해 주세요.';}render();}
async function cancelScan(){if(!scanning)return;controller?.abort();try{await fetch(scanEndpoint+'/api/cancel',{method:'POST',signal:AbortSignal.timeout(3000)});}catch{} }
async function scan(){
  if(scanning)return;if(state.mode==='demo'){storeModal();return;}
  if(!state.restaurant.placeId){storeModal();return;}if(!state.results.length){keywordsModal();return;}
  const endpoint=collectorEndpoint();
  if(!validEndpoint(endpoint)){settingsModal();return;}
  try{const health=await checkHealth(endpoint);if(state.settings.searchLocation&&!health.supportsSearchLocation){toast('검색 지역을 적용하려면 실행 창을 닫고 시작하기.cmd를 다시 실행해 주세요.');return;}if(health.scanActive){toast('이전 조회가 종료되는 중입니다. 잠시 후 다시 측정해 주세요.');return;}if(!health.collectorReady){toast(health.message||'수집기의 Playwright 브라우저를 준비해 주세요.');settingsModal();return;}}catch{toast('시작하기.cmd를 더블클릭해 파이썬 수집기를 실행해 주세요.');settingsModal();return;}
  scanEndpoint=endpoint;scanning=true;controller=new AbortController();$('#scan-button').hidden=true;$('#cancel-scan').hidden=false;let done=0,failed=0,consecutiveFailures=0;
  const queue=state.results.filter(r=>!selected.size||selected.has(r.keyword)).map(r=>r.keyword),restaurant={...state.restaurant},settings={...state.settings};render();
  for(const keyword of queue){if(controller.signal.aborted)break;$('#scan-status').textContent=`${deviceLabel(settings.device)} 측정 중 ${done+1}/${queue.length} · ${keyword}`;
    const target=state.results.find(r=>r.keyword===keyword);if(!target)continue;
    try{const response=await fetch(endpoint+'/api/check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({restaurant,keywords:[keyword],maxDepth:settings.maxDepth,region:settings.region,device:settings.device,location:settings.searchLocation||null}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(100000)])});let data=await response.json();if(!response.ok)throw Error(data.error||data.message||'수집기 응답 오류');const result=data.results?.find(r=>r.keyword===keyword&&r.device===settings.device);if(!result)throw Error('수집기 결과 형식을 확인해 주세요.');if(result.status!=='success')throw Error(result.error||'측정을 완료하지 못했어요.');
      for(const k of ['organicRank','adRank'])if(result[k]!==null&&(!Number.isInteger(result[k])||result[k]<1))throw Error('유효하지 않은 순위 데이터입니다.');
      if(!Number.isInteger(result.maxDepth)||result.maxDepth<0||result.maxDepth>settings.maxDepth||result.organicRank>result.maxDepth)throw Error('유효하지 않은 관측 범위입니다.');
      if(!result.observedAt||!Number.isFinite(Date.parse(result.observedAt)))throw Error('측정 시각이 누락됐어요.');
      if(settings.searchLocation&&(result.locationApplied!==true||!result.searchLocation||searchLocationKey(result.searchLocation)!==searchLocationKey(settings.searchLocation)))throw Error('선택한 검색 지역의 실제 적용을 확인하지 못했습니다.');
      consecutiveFailures=0;
      const previous=target.status==='success'?{observedAt:target.observedAt,organicRank:target.organicRank,adRank:target.adRank}:null;
      const history=[...(target.history||[]),...(previous?[previous]:[])].slice(-90);
      Object.assign(target,result,{previousRank:previous?.organicRank??null,history,source:'naver-map',error:undefined});
    }catch(error){if(controller.signal.aborted)break;failed++;consecutiveFailures++;target.history=[...(target.history||[]),...(target.status==='success'?[{observedAt:target.observedAt,organicRank:target.organicRank,adRank:target.adRank}]:[])].slice(-90);Object.assign(target,{status:'error',organicRank:null,adRank:null,previousRank:null,error:error.message,observedAt:new Date().toISOString(),device:settings.device,region:settings.region,maxDepth:settings.maxDepth,source:'naver-map',requestedSearchLocation:settings.searchLocation||null,locationApplied:false,locationMode:settings.searchLocation?'custom-geolocation':'naver-default'});}
    done++;persist();render();
    if(consecutiveFailures>=3){toast('연속 3회 측정에 실패해 조회를 멈췄어요. 오류 상세와 수집기 상태를 확인하세요.');break;}
  }
  scanning=false;$('#scan-button').hidden=false;$('#cancel-scan').hidden=true;render();toast(`${done}개 측정 처리 · 성공 ${done-failed}개 · 오류 ${failed}개${controller.signal.aborted?' · 중단됨':''}`);
}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function saveReport(type){state.reports??=[];state.reports.push({name:state.restaurant.name+' '+locationName()+' '+deviceLabel(state.activeDevice)+' 키워드 성장 리포트',date:new Date().toISOString(),count:state.results.length,mode:state.mode,type});state.reports=state.reports.slice(-30);persist();}
function exportCSV(){const headers=['keyword','organicRank','adRank','observedAt','placeId','restaurant','device','region','maxDepth','source','originalSource','clientMode','locationMode','searchLocationLabel','searchLatitude','searchLongitude','locationApplied','locationVerification','status','error'];download(`place-rank-${state.mode}-${new Date().toISOString().slice(0,10)}.csv`,csvEncode([headers,...allDeviceRows(state).map(r=>headers.map(k=>k==='restaurant'?state.restaurant.name:k==='placeId'?r.placeId||state.restaurant.placeId:k==='searchLocationLabel'?(r.searchLocation||r.requestedSearchLocation)?.label:k==='searchLatitude'?(r.searchLocation||r.requestedSearchLocation)?.latitude:k==='searchLongitude'?(r.searchLocation||r.requestedSearchLocation)?.longitude:k==='locationVerification'&&r[k]&&typeof r[k]==='object'?JSON.stringify(r[k]):r[k]))]),'text/csv;charset=utf-8');saveReport('CSV');closeModal();toast('현재 검색 지역의 PC·모바일 데이터를 CSV로 내보냈어요.');}
function printReport(){closeModal();const original={filter,search,page};filter='all';search='';page=1;renderTable(true);document.body.classList.add('printing');const restore=()=>{document.body.classList.remove('printing');filter=original.filter;search=original.search;page=original.page;renderTable();};window.addEventListener('afterprint',restore,{once:true});saveReport('PDF / 인쇄');window.print();}

$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{
  if(scanning)throw Error('조회가 끝난 뒤 가져와 주세요.');if(file.size>5*1024*1024)throw Error('5MB 이하 파일을 선택해 주세요.');
  const rows=parseImport(await file.text(),file.name.toLowerCase());const ids=[...new Set(rows.map(r=>r.placeId).filter(Boolean))],names=[...new Set(rows.map(r=>r.restaurant).filter(Boolean))];
  if(ids.length>1||names.length>1)throw Error('한 매장의 데이터만 가져올 수 있어요.');
  if(state.mode!=='demo'&&state.restaurant.placeId&&ids.length&&ids[0]!==state.restaurant.placeId)throw Error('등록된 매장과 파일의 플레이스 ID가 다릅니다. 매장을 먼저 변경해 주세요.');
  if(state.mode!=='demo'&&state.restaurant.placeId&&names.length&&names[0]!==state.restaurant.name)throw Error('등록된 매장과 파일의 매장명이 다릅니다.');
  const importLocation=rows[0].searchLocation||rows[0].requestedSearchLocation||null;
  if(new Set(rows.map(row=>searchLocationKey(row.searchLocation||row.requestedSearchLocation||null))).size>1)throw Error('한 파일에는 한 검색 지역의 기록만 담아 주세요. 지역별로 나눠 가져올 수 있어요.');
  const working=structuredClone(state);normalizeDeviceState(working);normalizeLocationState(working);
  if(working.mode==='demo'){working.mode='import';working.deviceResults={desktop:[],mobile:[]};working.results=[];working.keywordRegistry=[];working.locationProfiles={};working.settings.searchLocation=null;working.locationKey='default';}
  changeSearchLocation(working,importLocation);const byDevice=structuredClone(working.deviceResults);
  for(const row of rows){const results=byDevice[row.device];const current=results.find(r=>r.keyword===row.keyword);if(!current){results.push(row);continue;}
    const points=[...(current.history||[]),...(current.status==='success'?[{observedAt:current.observedAt,organicRank:current.organicRank,adRank:current.adRank}]:[])];
    if(!current.observedAt||Date.parse(row.observedAt)>=Date.parse(current.observedAt)){Object.assign(current,row,{history:points.slice(-90),previousRank:current.status==='success'?current.organicRank:null});}
    else if(row.status==='success'){current.history=[...points,{observedAt:row.observedAt,organicRank:row.organicRank,adRank:row.adRank}].slice(-90);}}
  if(new Set([...working.keywordRegistry,...DEVICES.flatMap(device=>byDevice[device].map(r=>r.keyword))]).size>1000)throw Error('가져온 후 총 키워드가 1,000개를 초과합니다.');
  working.mode='import';working.deviceResults=byDevice;working.activeDevice=(rows.find(row=>row.status==='success')||rows[0]).device;working.results=byDevice[working.activeDevice];
  working.restaurant={...working.restaurant,name:names[0]||(!working.restaurant.placeId?'가져온 매장':working.restaurant.name),placeId:ids[0]||working.restaurant.placeId,address:rows[0].region};
  working.settings={...working.settings,region:rows[0].region,maxDepth:Math.min(100,Math.max(20,rows[0].maxDepth)),device:working.activeDevice};
  syncDeviceRows(working);stashCurrentLocation(working);state=working;selected.clear();page=1;persist();render();closeModal();toast(`${rows.length}개 기록을 검색 지역·기기별로 가져왔어요.`);
}catch(error){toast(error.message);}finally{e.target.value='';}});
$('#keyword-search').addEventListener('input',e=>{search=e.target.value.toLowerCase().trim();page=1;renderTable();});
$('#keyword-tbody').addEventListener('change',e=>{if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);renderTable();}});
$('#select-all').addEventListener('change',e=>{filteredResults().slice((page-1)*PAGE_SIZE,page*PAGE_SIZE).forEach(r=>e.target.checked?selected.add(r.keyword):selected.delete(r.keyword));renderTable();});
$('#delete-selected').addEventListener('click',()=>{if(scanning){toast('조회가 끝난 뒤 삭제해 주세요.');return;}const n=selected.size;removeKeywords(state,selected);selected.clear();persist();render();toast(`${n}개 키워드를 삭제했어요.`);});
$('#close-modal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#scan-button').addEventListener('click',scan);$('#cancel-scan').addEventListener('click',cancelScan);$('#quick-scan-button').addEventListener('click',scan);$('#quick-cancel-scan').addEventListener('click',cancelScan);
$('#mobile-menu').addEventListener('click',()=>document.body.classList.toggle('sidebar-open'));
document.querySelector('[data-view="dashboard"]').addEventListener('click',()=>{closeModal();document.body.classList.remove('sidebar-open');window.scrollTo({top:0,behavior:'smooth'});});
